import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    types = []
    for _ in range(n):
        types.append(int(next(iterator)))

    incoming = [0] * (n + 1)
    for i in range(1, n + 1):
        incoming[i] = int(next(iterator))

    outgoing = [0] * (n + 1)
    for i, u in enumerate(incoming[1:], start=1):
        if u != 0:
            outgoing[u] = i

    best_k = 0
    best_path_start = 1

    for i in range(1, n + 1):
        if types[i - 1] == 1:
            current_len = 0
            curr = i
            while curr != 0:
                prev = incoming[curr]
                if prev != 0 and types[prev - 1] == 0:
                    current_len += 1
                    curr = prev
                else:
                    break

            if current_len + 1 > best_k:
                best_k = current_len + 1
                best_path_start = curr

    path = list(range(best_path_start, best_path_start + best_k))

    print(best_k)
    print(' '.join(map(str, path)))

if __name__ == "__main__":
    main()
